-- Each plan owns its checked constants; dynamic EXECUTE creates fresh plans.
CREATE SEQUENCE input_check_counter;
CREATE TYPE input_choice AS ENUM('a');
CREATE DOMAIN input_checked AS input_choice CHECK(nextval('input_check_counter')>0);
CREATE FUNCTION input_sql() RETURNS input_checked[] LANGUAGE sql AS 'SELECT ''{a}''::input_checked[]';
SELECT 'created',last_value,is_called FROM input_check_counter;
CREATE FUNCTION input_sql() RETURNS input_checked[] LANGUAGE sql AS 'SELECT ''{a}''::input_checked[]';
CREATE OR REPLACE FUNCTION input_sql() RETURNS text LANGUAGE sql AS 'SELECT ''{a}''::input_checked[]';
SELECT 'rejected',last_value FROM input_check_counter;
SELECT input_sql() FROM generate_series(1,3);
SELECT 'one_call_site',last_value FROM input_check_counter;
CREATE FUNCTION input_pl() RETURNS input_checked[] LANGUAGE plpgsql AS $$BEGIN RETURN '{a}'::input_checked[]; END$$;
SELECT input_pl();
SELECT input_pl();
SELECT 'static_reused',last_value FROM input_check_counter;
CREATE FUNCTION input_dynamic() RETURNS input_checked[] LANGUAGE plpgsql AS $$DECLARE value input_checked[]; BEGIN EXECUTE 'SELECT ''{a}''::input_checked[]' INTO value; RETURN value; END$$;
SELECT input_dynamic();
SELECT input_dynamic();
SELECT 'dynamic_fresh',last_value FROM input_check_counter;
PREPARE input_prepared AS SELECT input_sql();
SELECT 'prepared',last_value FROM input_check_counter;
EXECUTE input_prepared;
EXECUTE input_prepared;
SELECT 'prepared_reused',last_value FROM input_check_counter;
SET check_function_bodies=off;
CREATE FUNCTION input_unchecked() RETURNS input_checked[] LANGUAGE sql AS 'SELECT ''{a}''::input_checked[]';
CREATE FUNCTION input_invalid_sql() RETURNS int LANGUAGE sql AS 'SELECT unknown_column';
CREATE FUNCTION input_invalid_pl() RETURNS int LANGUAGE plpgsql AS 'malformed body';
SELECT 'validation_disabled',last_value FROM input_check_counter;
SET check_function_bodies=on;
SELECT input_unchecked();
SELECT 'validated_on_use',last_value FROM input_check_counter;
CREATE SCHEMA input_private;
CREATE TYPE input_private.choice AS ENUM('a');
CREATE DOMAIN input_private.checked AS input_private.choice CHECK(nextval('input_check_counter')>0);
CREATE FUNCTION input_configured() RETURNS input_private.checked[] LANGUAGE sql SET search_path=input_private,public AS 'SELECT ''{a}''::checked[]';
SELECT 'configured',last_value,current_setting('search_path') FROM input_check_counter;
DEALLOCATE input_prepared;
DROP FUNCTION input_sql(),input_pl(),input_dynamic(),input_unchecked(),input_invalid_sql(),input_invalid_pl(),input_configured();
DROP DOMAIN input_checked;
DROP TYPE input_choice;
DROP DOMAIN input_private.checked;
DROP TYPE input_private.choice;
DROP SCHEMA input_private;
DROP SEQUENCE input_check_counter;
